/**
 *
 * DataTableTBody is a component that displays the body content inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTBody
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { RowGroupMeta } from '@primereact/types/headless/datatable';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Options passed to the DataTableTBody children render prop via instance.
 */
export interface DataTableTBodyItemOptions {
    /**
     * The data object for the current row.
     */
    item: Record<string, unknown>;
    /**
     * The index of the item in the data array.
     */
    index: number;
    /**
     * The group metadata for this row, only present when groupField is set.
     */
    groupMeta?: RowGroupMeta;
}
/**
 * Defines passthrough(pt) options type in DataTableTBody component.
 */
export type DataTableTBodyPassThroughType<E> = PassThroughType<DataTableTBodyInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTBody component.
 */
export interface DataTableTBodyPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTBodyPassThroughType<React.HTMLAttributes<HTMLTableSectionElement>>;
}
/**
 * Defines valid properties in DataTableTBody component.
 */
export interface DataTableTBodyProps extends BaseComponentProps<DataTableTBodyInstance, unknown, DataTableTBodyPassThrough, 'tbody'> {
    /**
     * Render function called for each item in the data array.
     * Receives the component instance enriched with item, index, and groupMeta.
     * @param instance The component instance with item context.
     * @returns The rendered content for the row.
     */
    children?: ((instance: DataTableTBodyInstance & DataTableTBodyItemOptions) => React.ReactNode) | React.ReactNode;
}
/**
 * Defines valid state in DataTableTBody component.
 */
export interface DataTableTBodyState {
}
/**
 * Defines the methods and properties exposed by DataTableTBody component.
 */
export interface DataTableTBodyExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTBody component.
 */
export type DataTableTBodyInstance = ComponentInstance<DataTableTBodyProps, DataTableTBodyState, DataTableTBodyExposes>;
